"},{"node":"useLinkMemo","qualified_name":"bench-repo.web.src.components.MemoEditor.hooks.useLinkMemo.useLinkMemo","label":"Function","file":"web/src/components/MemoEditor/hooks/useLinkMemo.ts","start_line":23,"end_line":89,"in_degree":1,"out_degree":4,"match_lines":[55],"source":"export const useLinkMemo = ({ isOpen, currentMemoName, existingRelations, onAddRelation }: UseLinkMemoParams) => {
  const user = useCurrentUser();
  const [searchText, setSearchText] = useState("");
  const [isFetching, setIsFetching] = useState(true);
  const [fetchedMemos, setFetchedMemos] = useState<Memo[]>([]);

  const filteredMemos = fetchedMemos.filter((memo) => memo.name !== currentMemoName);

  const linkedMemoNames = useMemo(() => new Set(existingRelations.map((r) => r.relatedMemo?.name)), [existingRelations]);

  const isAlreadyLinked = (memoName: string): boolean => linkedMemoNames.has(memoName);

  useEffect(() => {
    if (isOpen) {
      setSearchText("");
    }
  }, [isOpen]);

  useDebouncedEffect(
    async () => {
      if (!isOpen) return;

      setIsFetching(true);
      try {
        const conditions: string[] = [];
        const creatorFilter = buildMemoCreatorFilter(user?.name ?? "");
        if (creatorFilter) {
          conditions.push(creatorFilter);
        }
        if (searchText) {
          conditions.push(`content.contains("${searchText}")`);
        }
        const { memos } = await memoServiceClient.listMemos({
          pageSize: DEFAULT_LIST_MEMOS_PAGE_SIZE,
          filter: conditions.join(" && "),
        });
        setFetchedMemos(memos);
      } catch (error) {
        console.error(error);
      } finally {
        setIsFetching(false);
      }
    },
    300,
    [isOpen, searchText],
  );

  const addMemoRelation = (memo: Memo) => {
    const relation = create(MemoRelationSchema, {
      type: MemoRelation_Type.REFERENCE,
      relatedMemo: create(MemoRelation_MemoSchema, {
        name: memo.name,
        snippet: memo.snippet,
      }),
    });
    onAddRelation(relation);
  };

  return {
    searchText,
    setSearchText,
    isFetching,
    filteredMemos,
    addMemoRelation,
    isAlreadyLinked,
  };
};
